import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type NotificationPopupsProps = Record<string, any>;

interface NotificationItemProps {
  data: NotificationPopupsProps["notifications"][0];
  index: number;
  totalNotifications: number;
  fps: number;
  cardBackgroundColor: string;
  textColor: string;
  subtextColor: string;
}

const NotificationItem: React.FC<NotificationItemProps> = ({ 
  data, 
  index, 
  totalNotifications,
  fps, 
  cardBackgroundColor, 
  textColor, 
  subtextColor 
}) => {
  const frame = useCurrentFrame();
  
  // Approximate height of a notification card + 24px gap
  const stepHeight = 146; 

  // Calculate total upward displacement caused by notifications appearing *after* this one
  let pushUpAmount = 0;
  for (let k = index + 1; k < totalNotifications; k++) {
    const pushAnim = spring({
      frame: frame - (k * 20),
      fps,
      config: { damping: 14, stiffness: 120, mass: 0.8 }
    });
    pushUpAmount += pushAnim * stepHeight;
  }

  const delay = index * 20; 
  const springAnim = spring({
    frame: frame - delay,
    fps,
    config: { damping: 14, stiffness: 120, mass: 0.8 }
  });
  
  const opacity = interpolate(springAnim, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  // Start from inside the phone and shoot up slightly
  const entryY = interpolate(springAnim, [0, 1], [150, 0], { extrapolateRight: "clamp" });
  const scale = interpolate(springAnim, [0, 1], [0.6, 1], { extrapolateRight: "clamp" });

  // Final vertical position combines its own entry animation and the push from newer notifications
  const translateY = entryY - pushUpAmount;

  return (
    <div style={{
      position: 'absolute',
      bottom: 0,
      left: 0,
      width: 800,
      zIndex: totalNotifications - index, // Older notifications sit on top of newer ones sliding in
      backgroundColor: cardBackgroundColor,
      backdropFilter: 'blur(24px)',
      WebkitBackdropFilter: 'blur(24px)',
      borderRadius: 36,
      padding: '24px 32px',
      boxSizing: 'border-box',
      display: 'flex',
      flexDirection: 'row',
      alignItems: 'center',
      boxShadow: '0px 20px 40px rgba(0,0,0,0.1), 0px 4px 12px rgba(0,0,0,0.05), inset 0 1px 1px rgba(255,255,255,0.8)',
      border: '1px solid rgba(255,255,255,0.4)',
      gap: 24,
      opacity,
      transform: `translateY(${translateY}px) scale(${scale})`,
      transition: 'none'
    }}>
      {/* Icon Container */}
      <div style={{
        width: 72, height: 72, borderRadius: 20,
        background: 'radial-gradient(circle at 30% 107%, #fdf497 0%, #fdf497 5%, #fd5949 45%, #d6249f 60%, #285AEB 90%)',
        display: 'flex', justifyContent: 'center', alignItems: 'center', flexShrink: 0,
        transition: 'none'
      }}>
        <svg width="44" height="44" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <rect x="2" y="2" width="20" height="20" rx="5" ry="5"></rect>
          <path d="M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z"></path>
          <line x1="17.5" y1="6.5" x2="17.51" y2="6.5"></line>
        </svg>
      </div>

      {/* Text Container */}
      <div style={{ display: 'flex', flexDirection: 'column', flex: 1, justifyContent: 'center', gap: 6, transition: 'none' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', transition: 'none' }}>
          <div style={{ fontSize: 26, color: textColor, letterSpacing: '-0.02em', lineHeight: 1.2, transition: 'none' }}>
            <span style={{ fontWeight: 600 }}>{data.username}</span> <span style={{ fontWeight: 500 }}>{data.action}</span>
          </div>
          <div style={{ fontSize: 22, fontWeight: 400, color: subtextColor, transition: 'none', marginLeft: 16 }}>
            {data.time}
          </div>
        </div>
        <div style={{ fontSize: 26, fontWeight: 400, color: textColor, letterSpacing: '-0.01em', lineHeight: 1.2, transition: 'none' }}>
          {data.message}
        </div>
      </div>
    </div>
  );
};

